const triggerData = $("UTM Link Builder Trigger").item.json;
const taxonomyRow = $json;

function norm(value) {
  return (value === null || value === undefined) ? "" : String(value).trim().toLowerCase();
}

const baseUrl = triggerData.baseUrl;
const program = norm(triggerData.program);
const campaign = norm(triggerData.campaign);
const content = norm(triggerData.content);
const term = norm(triggerData.term);

const utmSource = norm(taxonomyRow.utmSource);
const utmMedium = norm(taxonomyRow.utmMedium);
const campaignType = norm(taxonomyRow.campaignType);

if (!baseUrl || !/^https?:\/\//i.test(baseUrl)) {
  return [{ json: { success: false, error: "Missing or invalid baseUrl (must start with http:// or https://): " + baseUrl, program: program } }];
}

if (!campaign) {
  return [{ json: { success: false, error: "Missing campaign for program \"" + program + "\"", program: program } }];
}

if (campaignType === "event") {
  const eventPattern = /^\d{4}-\d{2}(-\d{2})?_?/;
  if (!eventPattern.test(campaign)) {
    return [{ json: { success: false, error: "Event-type campaign \"" + campaign + "\" should start with YYYY-MM or YYYY-MM-DD", program: program } }];
  }
}

const params = [];
params.push("utm_source=" + encodeURIComponent(utmSource));
params.push("utm_medium=" + encodeURIComponent(utmMedium));
params.push("utm_campaign=" + encodeURIComponent(campaign));
if (content) {
  params.push("utm_content=" + encodeURIComponent(content));
}
if (term) {
  params.push("utm_term=" + encodeURIComponent(term));
}
const queryString = params.join("&");
const separator = baseUrl.indexOf("?") === -1 ? "?" : "&";
const finalUrl = baseUrl + separator + queryString;

return [{
  json: {
    success: true,
    url: finalUrl,
    program: program,
    utmSource: utmSource,
    utmMedium: utmMedium,
    utmCampaign: campaign,
    utmContent: content || null
  }
}];

const triggerData = $("UTM Link Builder Trigger").item.json;
const program = triggerData.program;

return [{
  json: {
    success: false,
    error: "Unknown program \"" + program + "\" \u2014 not found in utm_taxonomy data table. Add it there before using it.",
    program: program
  }
}];
